"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60398"],{62792(e){e.exports=JSON.parse('{"id":"FIN-434","slug":"bermudan-option","term":"Bermudan Option","also_known_as":[],"difficulty":"Intermediate","definition":"A Bermudan option is an option that can be exercised only on certain specified dates before expiry, as well as on the expiration date itself.","explanation":["Bermudan options sit between European and American options. A European option can be exercised only at expiry. An American option can be exercised at any time. A Bermudan option can be exercised on a set schedule, such as once a month or once a quarter. The name is a playful reference to Bermuda being located between Europe and America.","For example, a Bermudan option with a one-year life might allow exercise on the last business day of each quarter. The holder can decide on each of those dates whether to exercise or wait.","Because they offer more flexibility than European options but less than American options, Bermudan options are typically priced between the two.","Bermudan options are mainly found in over-the-counter markets, particularly in interest rate products. A common example is a Bermudan swaption, which gives the right to enter an interest rate swap on certain dates. They are also embedded in some callable bonds, which the issuer can repay early only on specific dates."],"note":"","total":1500,"prev":{"slug":"beneficiary","term":"Beneficiary"},"next":{"slug":"best-case-scenario","term":"Best-Case Scenario"}}')}}]);